function resolveEffectiveOwner(data){
  const configuration=data.configuration??{};
  const nodes=Array.isArray(configuration.nodes)?configuration.nodes:[];
  const owners=Array.isArray(configuration.owners)?configuration.owners:[];
  const nodesByRef=new Map(nodes.map((node)=>[node.node_ref,node]));
  const ownersByRef=new Map(owners.map((owner)=>[owner.owner_ref,owner]));
  const visited=new Set();
  let node=nodesByRef.get(configuration.selected_node_ref);

  while(node&&!visited.has(node.node_ref)){
    visited.add(node.node_ref);
    if(node.owner_ref!=null){
      return ownersByRef.get(node.owner_ref)?.display_name??node.owner_ref;
    }
    node=nodesByRef.get(node.parent_ref);
  }

  return "Owner unavailable";
}
